  ["IPAS||Bunyi||Teknologi Bunyi"]: [
    {"question":"Sebuah kapal menggunakan sonar untuk mengukur kedalaman laut. Bunyi dipancarkan dari kapal dan setelah 2 detik, bunyi pantul diterima kembali. Jika cepat rambat bunyi di air laut adalah 1500 m/s, berapakah kedalaman laut tersebut?","options":["750 m","1500 m","3000 m","375 m"],"correctIndex":1,"explanation":"Rumus kedalaman laut adalah s = (v × t) / 2. Maka, s = (1500 m/s × 2 s) / 2 = 1500 meter."},
    {"question":"Berikut ini adalah gelombang bunyi yang memiliki frekuensi 50.000 Hz. Termasuk golongan gelombang apakah bunyi tersebut?","options":["Infrasonik","Audiosonik","Ultrasonik","Supersonik"],"correctIndex":2,"explanation":"Gelombang bunyi dengan frekuensi di atas 20.000 Hz termasuk ultrasonik. Karena 50.000 Hz > 20.000 Hz, maka termasuk ultrasonik."},
    {"question":"Prinsip kerja USG (Ultrasonografi) dalam bidang kesehatan adalah menggunakan gelombang bunyi dengan frekuensi...","options":["sangat rendah (infrasonik)","sangat tinggi (ultrasonik)","sedang (audiosonik)","tidak menentu"],"correctIndex":1,"difficulty":"medium","explanation":"USG menggunakan gelombang ultrasonik, yaitu gelombang bunyi dengan frekuensi di atas 20.000 Hz yang tidak dapat didengar manusia, untuk menghasilkan gambar organ dalam tubuh."},
    {"question":"Salah satu contoh pemanfaatan teknologi bunyi dalam kehidupan sehari-hari adalah...","options":["lampu senter","telepon genggam","kipas angin","kompor gas"],"correctIndex":1,"difficulty":"easy","explanation":"Telepon genggam menggunakan teknologi bunyi untuk mengubah suara menjadi sinyal listrik dan sebaliknya, sehingga kita dapat berkomunikasi jarak jauh."},
    {"question":"Pada sistem sonar, gelombang bunyi dipancarkan, lalu dipantulkan oleh benda. Waktu yang diperlukan gelombang untuk kembali digunakan untuk menghitung...","options":["warna benda","suhu air","jarak benda","kecepatan kapal"],"correctIndex":2,"difficulty":"medium","explanation":"Dengan mengukur waktu tempuh gelombang bunyi dari pemancar ke benda dan kembali, sonar dapat menghitung jarak benda tersebut berdasarkan kecepatan rambat bunyi di air."},
    {"question":"Sebuah kapal menggunakan sonar untuk mengukur kedalaman laut. Bunyi dipancarkan dari kapal dan setelah 2 detik, bunyi pantul diterima kembali. Jika cepat rambat bunyi di air laut adalah 1500 m/s, berapakah kedalaman laut tersebut?","options":["750 m","1500 m","3000 m","375 m"],"correctIndex":1,"explanation":"Bunyi menempuh jarak pergi-pulang dalam 2 detik, sehingga waktu tempuh ke dasar adalah 1 detik. Dengan cepat rambat 1500 m/s, kedalaman = 1500 m."},
    {"question":"Berikut ini adalah gelombang bunyi yang memiliki frekuensi 50.000 Hz. Termasuk golongan gelombang apakah bunyi tersebut?","options":["Infrasonik","Audiosonik","Ultrasonik","Supersonik"],"correctIndex":2,"explanation":"Gelombang bunyi dengan frekuensi di atas 20.000 Hz termasuk ultrasonik. 50.000 Hz > 20.000 Hz, jadi termasuk ultrasonik."},
  ],

  ["Matematika||Pecahan||Penjumlahan Pecahan Berpenyebut Sama"]: [
    {"question":"Berapa hasil dari 1/5 + 2/5?","options":["3/5","3/10","2/5","1/5"],"correctIndex":0,"difficulty":"medium","explanation":"Penjumlahan pecahan berpenyebut sama cukup jumlahkan pembilangnya: 1 + 2 = 3, penyebut tetap 5."},
    {"question":"Hitunglah 3/8 + 2/8!","options":["5/8","5/16","5/64","1/8"],"correctIndex":0,"difficulty":"medium","explanation":"Penyebut sama (8), jumlahkan pembilang: 3 + 2 = 5, sehingga hasilnya 5/8."},
    {"question":"Berapa hasil dari 2/7 + 3/7 + 1/7?","options":["6/7","6/21","6/343","5/7"],"correctIndex":0,"difficulty":"medium","explanation":"Ketiga pecahan berpenyebut sama (7), jumlahkan semua pembilang: 2 + 3 + 1 = 6, hasilnya 6/7."},
    {"question":"Andi memiliki 4/9 potong kue dan menerima 3/9 potong kue lagi. Berapa kue yang dimiliki Andi sekarang?","options":["7/9","7/18","7/81","1/9"],"correctIndex":0,"difficulty":"medium","explanation":"Jumlahkan kue Andi: 4/9 + 3/9 = (4+3)/9 = 7/9 potong kue."},
    {"question":"Hasil dari 5/12 + 4/12 adalah...","options":["9/12","3/4","9/24","1/12"],"correctIndex":0,"difficulty":"medium","explanation":"5/12 + 4/12 = (5+4)/12 = 9/12. Pecahan ini bisa disederhanakan menjadi 3/4, tetapi jawaban yang tepat sesuai operasi adalah 9/12."},
  ],

  ["Matematika||Pecahan||Penjumlahan Pecahan Berpenyebut Berbeda"]: [
    {"question":"Berapakah hasil dari 1/3 + 1/6?","options":["2/9","1/2","1/6","4/6"],"correctIndex":1,"difficulty":"medium","explanation":"Samakan penyebut: 1/3 = 2/6. Lalu jumlahkan: 2/6 + 1/6 = 3/6. Sederhanakan 3/6 menjadi 1/2."},
    {"question":"Berapa hasil dari 2/7 + 3/14?","options":["1/2","5/14","7/21","5/21"],"correctIndex":0,"difficulty":"medium","explanation":"Ubah 2/7 menjadi 4/14 agar penyebut sama. Lalu: 4/14 + 3/14 = 7/14. Sederhanakan 7/14 menjadi 1/2."},
    {"question":"2/5 + 1/4 = ...","options":["13/20","3/9","3/20","8/20"],"correctIndex":0,"difficulty":"medium","explanation":"KPK dari 5 dan 4 adalah 20. Ubah: 2/5 = 8/20 dan 1/4 = 5/20. Jumlahkan: 8/20 + 5/20 = 13/20."},
    {"question":"Hasil penjumlahan 3/8 + 1/2 adalah ...","options":["7/8","4/10","7/16","4/8"],"correctIndex":0,"difficulty":"medium","explanation":"Samakan penyebut: 1/2 = 4/8. Kemudian: 3/8 + 4/8 = 7/8."},
    {"question":"Berapa hasil dari 2/7 + 3/14?","options":["7/14","5/14","7/21","5/21"],"correctIndex":0,"difficulty":"medium","explanation":"Ubah 2/7 menjadi 4/14 agar penyebut sama. Lalu: 4/14 + 3/14 = 7/14."},
  ],

  ["Matematika||Pecahan||Pengurangan Pecahan Berpenyebut Sama"]: [
    {"question":"Hasil dari 5/7 - 2/7 adalah...","options":["3/7","7/7","3/14","2/7"],"correctIndex":0,"difficulty":"medium","explanation":"Pengurangan pecahan berpenyebut sama cukup kurangi pembilangnya saja. 5-2=3, maka hasilnya 3/7."},
    {"question":"Berapa hasil dari 8/9 - 3/9?","options":["5/9","11/9","5/18","3/9"],"correctIndex":0,"difficulty":"medium","explanation":"8/9 - 3/9 = (8-3)/9 = 5/9. Penyebut tetap 9, hanya kurangi pembilang 8 dengan 3."},
    {"question":"Ibu memiliki 4/5 bagian kue. Karena dimakan tamu, sisa kue menjadi 1/5 bagian. Berapa bagian kue yang dimakan tamu?","options":["3/5","5/5","3/10","1/5"],"correctIndex":0,"difficulty":"medium","explanation":"Kue dimakan tamu = 4/5 - 1/5 = (4-1)/5 = 3/5 bagian kue."},
    {"question":"Hasil dari 11/12 - 5/12 disederhanakan menjadi...","options":["1/2","6/12","6/24","5/12"],"correctIndex":0,"difficulty":"medium","explanation":"11/12 - 5/12 = 6/12. Sederhanakan 6/12 dengan membagi pembilang dan penyebut sama-sama 6, hasilnya 1/2."},
    {"question":"Andi memiliki tali sepanjang 7/8 meter, lalu digunakan 3/8 meter. Sisa tali Andi adalah...","options":["1/2","10/8","4/16","3/8"],"correctIndex":0,"difficulty":"medium","explanation":"Sisa tali = 7/8 - 3/8 = 4/8 = 1/2 meter (4/8 disederhanakan dengan FPB 4)."},
  ],

  ["Matematika||Pecahan||Pengurangan Pecahan Berpenyebut Berbeda"]: [
    {"question":"Hasil dari 9/10 - 2/5 + 1/2 adalah...","options":["9/10","1","4/5","3/10"],"correctIndex":1,"difficulty":"medium","explanation":"9/10 - 4/10 + 5/10 = 10/10 = 1. KPK 10, 5, dan 2 adalah 10."},
    {"question":"Hitunglah 7/8 - 1/2!","options":["6/6","3/8","6/8","1/4"],"correctIndex":1,"difficulty":"medium","explanation":"7/8 - 1/2 = 7/8 - 4/8 = 3/8. KPK 8 dan 2 adalah 8."},
    {"question":"Pak Budi memiliki 1 1/4 kg gula. Ia menggunakan 2/5 kg untuk membuat kue. Sisa gula Pak Budi adalah...","options":["17/20 kg","1 3/20 kg","21/20 kg","1/20 kg"],"correctIndex":0,"difficulty":"medium","explanation":"1 1/4 - 2/5 = 5/4 - 2/5 = 25/20 - 8/20 = 17/20 kg. KPK 4 dan 5 adalah 20."},
    {"question":"Berapakah hasil dari 5/6 - 1/3 - 1/2?","options":["3/6","0","1/6","2/3"],"correctIndex":1,"difficulty":"medium","explanation":"5/6 - 1/3 - 1/2 = 5/6 - 2/6 - 3/6 = 0. KPK 6, 3, 2 adalah 6."},
    {"question":"Hasil dari 9/10 - 2/5 + 1/2 adalah...","options":["9/10","1 1/10","4/5","3/10"],"correctIndex":1,"difficulty":"medium","explanation":"9/10 - 2/5 + 1/2 = 9/10 - 4/10 + 5/10 = 10/10 = 1 1/10. KPK 10, 5, 2 adalah 10."},
  ],

