  ["Matematika||Bangun Ruang||Volume Prisma Segitiga"]: [
    {"question":"Sebuah prisma segitiga memiliki alas segitiga dengan alas = 6 cm dan tinggi = 4 cm. Jika tinggi prisma = 10 cm, berapakah volume prisma segitiga tersebut?","options":["120 cm³","240 cm³","140 cm³","100 cm³"],"correctIndex":0,"difficulty":"medium","explanation":"Volume = (½ × alas × tinggi segitiga) × tinggi prisma = (½ × 6 × 4) × 10 = 12 × 10 = 120 cm³"},
    {"question":"Prisma segitiga memiliki volume 360 cm³. Alas segitiganya memiliki alas 12 cm dan tinggi 6 cm. Berapakah tinggi prisma tersebut?","options":["8 cm","10 cm","12 cm","15 cm"],"correctIndex":1,"difficulty":"medium","explanation":"Luas alas = ½ × 12 × 6 = 36 cm². Tinggi = Volume ÷ Luas alas = 360 ÷ 36 = 10 cm"},
    {"question":"Kolam renang berbentuk prisma segitiga memiliki alas segitiga dengan panjang alas 15 m dan tinggi 8 m. Jika panjang kolam 25 m, berapa volume kolam tersebut?","options":["1500 m³","3000 m³","750 m³","1200 m³"],"correctIndex":0,"difficulty":"medium","explanation":"Volume = (½ × 15 × 8) × 25 = 60 × 25 = 1500 m³"},
    {"question":"Sebuah tenda berbentuk prisma segitiga dengan alas segitiga = 2 m dan tinggi segitiga = 1,5 m. Jika volume tenda = 9 m³, berapakah panjang tenda?","options":["4 m","5 m","6 m","8 m"],"correctIndex":2,"difficulty":"medium","explanation":"Luas alas = ½ × 2 × 1,5 = 1,5 m². Panjang = Volume ÷ Luas alas = 9 ÷ 1,5 = 6 m"},
    {"question":"Diketahui prisma segitiga dengan alas = 10 cm, tinggi segitiga = 8 cm, dan tinggi prisma = 12 cm. Berapakah volume prisma tersebut?","options":["380 cm³","480 cm³","960 cm³","9600 cm³"],"correctIndex":1,"difficulty":"medium","explanation":"Volume = (½ × 10 × 8) × 12 = 40 × 12 = 480 cm³"},
  ],

